  # dconf настройки GNOME (применяются без перелогина через home-manager switch)
  dconf.settings = {
    # GNOME Shell - расширения
    "org/gnome/shell" = {
      disable-user-extensions = false;
      enabled-extensions = [
        "appindicatorsupport@rgcjonas.gmail.com"
        "dash-to-dock@micxgx.gmail.com"
        "blur-my-shell@aunetx"
        "caffeine@patapon.info"
        "tophat@fflewddur.github.io"
        "app-hider@linth.dev"
        "clipboard-history@alexsaveau.dev"
        "azclock@azclock.gitlab.com"
        "lockscreen-extension@pratap.fastmail.fm"
        "window-calls@domandoman.xyz"
      ];
    };

    # Dash to Dock
    "org/gnome/shell/extensions/dash-to-dock" = {
      dock-position = "BOTTOM";
      intellihide = true;
      show-trash = true;
      show-show-apps-button = false;
    };

    # Blur My Shell
    "org/gnome/shell/extensions/blur-my-shell" = {
      brightness = 0.75;
      noise-amount = 0;
    };

    # Раскладки клавиатуры
    "org/gnome/desktop/input-sources" = {
      sources = [
        (lib.gvariant.mkTuple [ "xkb" "us" ])
        (lib.gvariant.mkTuple [ "xkb" "ru" ])
      ];
      xkb-options = [ "grp:shift_alt_toggle" ];
    };

    # Кнопки окон - кнопки справа (без maximize)
    "org/gnome/desktop/wm/preferences" = {
      button-layout = ":appmenu,minimize,close";
    };

    # Горячие клавиши оконного менеджера
    "org/gnome/desktop/wm/keybindings" = {
      switch-input-source = [ "<Shift>Alt_L" ];
      switch-input-source-backward = [ "<Shift>Alt_R" ];
    };

    # Интерфейс
    "org/gnome/desktop/interface" = {
      cursor-theme = "Bibata-Modern-Ice";
      cursor-size = lib.gvariant.mkInt32 24;
      enable-hot-corners = false;
    };
  };
}

